    fi
    prev="$3"
    cmd=""
    opts=""

    for i in "${COMP_WORDS[@]:0:COMP_CWORD}"
    do
        case "${cmd},${i}" in
            ",$1")
                cmd="todors"
                ;;
            todors,a)
                cmd="todors__subcmd__add"
                ;;
            todors,add)
                cmd="todors__subcmd__add"
