if [[ "${BASH_VERSINFO[0]}" -eq 4 && "${BASH_VERSINFO[1]}" -ge 4 || "${BASH_VERSINFO[0]}" -gt 4 ]]; then
    complete -F _todors -o nosort -o bashdefault -o default todors
else
    complete -F _todors -o bashdefault -o default todors
fi
